 const auto sizes=w.allocation_sizes(),frees=w.free_order();need(h.addresses.size()==sizes.size()&&h.allocation_flags.size()==sizes.size()&&h.snapshots.size()==frees.size(),"1048 completeallocation/prefreeinventory");Observation o;o.events=h.events();unsigned e=0u;const auto alloc=[&](unsigned id){need(e<o.events.size(),"1048 allocateeventexists");const auto&v=o.events[e++];need(v.kind==b::Event::Kind::allocate&&v.ordinal==id&&v.size==sizes[id]&&v.address==h.addresses[id]&&v.result==v.address&&h.allocation_flags[id]==0u,"1048 actualalloc exactordinal/size/flags/address/result");};const auto release=[&](unsigned id){need(e+3u<=o.events.size(),"1048 freeeventexists");const auto&a=o.events[e++],&z=o.events[e++],&v=o.events[e++];need(a.kind==b::Event::Kind::enter_lock&&z.kind==b::Event::Kind::leave_lock&&a.address==z.address&&a.address==*reinterpret_cast<const unsigned*>(std::uintptr_t(0x81729cu))&&a.ordinal==0u&&z.ordinal==0u&&a.size==0u&&z.size==0u&&a.result==0u&&z.result==0u,"1048 genuineCRTlock9 exactorder/state");need(v.kind==b::Event::Kind::release&&v.ordinal==id&&v.size==sizes[id]&&v.address==h.addresses[id]&&v.result!=0u,"1048 actualfree exactordinal/size/rawaddress/BOOL");};
 for(unsigned k=0;k<w.fixture_count();++k)alloc(k);if(w.root==0x12f900u)alloc(w.c.count-1u);if(w.root==0x12fae0u)release(w.c.index);if(w.root==0x27f180u){for(unsigned k=w.c.count;k--!=0u;)release(k);release(w.c.count);alloc(w.c.count+1u);release(w.c.count+1u);}need(e==o.events.size(),"1048 no unobservedheap events");
 auto ei=bi,ea=ba;w.expected_memory(ei,ea,h);need(std::equal(ei.begin(),ei.end(),image)&&std::equal(ea.begin(),ea.end(),arena),"1048 independentfull7503872image/1MiBarena oracle");o.image=ei;o.arena=ea;w.normalize_arena(o.arena,h);o.normalizations=(w.root==0x12f900u||w.root==0x12fae0u)?w.c.count:0u;
