 auto live=h.live();std::sort(live.begin(),live.end(),[](const auto&a,const auto&b){return a.ordinal<b.ordinal;});need(live.size()+frees.size()==sizes.size(),"1048 allownedblocks eitherliveorfreed");for(const auto&l:live){need(l.address==h.addresses[l.ordinal]&&l.bytes==sizes[l.ordinal]&&std::find(frees.begin(),frees.end(),l.ordinal)==frees.end(),"1048 exactliveownedidentity");auto bytes=std::vector<unsigned char>(reinterpret_cast<const unsigned char*>(std::uintptr_t(l.address)),reinterpret_cast<const unsigned char*>(std::uintptr_t(l.address))+l.bytes);need(bytes==w.block_expected(l.ordinal,h),"1048 entirelive roundedblockincludingtail");o.live.push_back(std::move(bytes));}
